import React, { useState, useEffect } from 'react';
import { Grid, Paper, Typography, Box } from '@mui/material';
import { getFinancialSummary, getStock, getIncome, getExpenses } from "../services/api";


const HomePage = () => {
  const [summary, setSummary] = useState(null);
  const [recentStock, setRecentStock] = useState([]);
  const [recentFinance, setRecentFinance] = useState([]);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [summ, stock, income, expenses] = await Promise.all([
        getFinancialSummary(),
        getStock({ limit: 5 }),
        getIncome({ limit: 5 }),
        getExpenses({ limit: 5 })
      ]);

      setSummary(summ);
      setRecentStock(stock);
      setRecentFinance([...income, ...expenses].sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 5));
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    }
  };

  return (
    <Grid container spacing={3} sx={{ padding: 4, background: '#f0f2f5', minHeight: '100vh' }}>
      <Grid item xs={12}>
        <Paper elevation={5} sx={{ p: 4, borderRadius: 4, background: 'rgba(255, 255, 255, 0.9)', backdropFilter: 'blur(10px)', boxShadow: '0px 8px 20px rgba(0, 0, 0, 0.15)' }}>
          <Typography variant="h5" gutterBottom sx={{ fontWeight: 'bold', color: '#333' }}>Financial Summary</Typography>
          {summary ? (
            <Grid container spacing={3}>
              {['Total Income', 'Total Expenses', 'Net Profit/Loss'].map((label, index) => (
                <Grid item xs={12} md={4} key={index}>
                  <Box sx={{ p: 3, textAlign: 'center', borderRadius: 3, backgroundColor: index === 1 ? '#ffebee' : '#e8f5e9', transition: 'transform 0.3s ease', '&:hover': { transform: 'scale(1.05)' } }}>
                    <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>{label}</Typography>
                    <Typography variant="h4" color={index === 1 ? 'error.main' : 'success.main'} sx={{ fontWeight: 'bold' }}>
                      ${[summary.totalIncome, summary.totalExpenses, summary.netProfit][index].toFixed(2)}
                    </Typography>
                  </Box>
                </Grid>
              ))}
            </Grid>
          ) : (
            <Typography>Loading...</Typography>
          )}
        </Paper>
      </Grid>

      {[{ title: 'Recent Stock Transactions', data: recentStock, headers: ['Item', 'Type', 'Qty', 'Amount'] },
        { title: 'Recent Financial Transactions', data: recentFinance, headers: ['Type', 'Category', 'Amount'] }].map((section, index) => (
        <Grid item xs={12} md={6} key={index}>
          <Paper elevation={5} sx={{ p: 4, height: '100%', borderRadius: 4, background: 'rgba(255, 255, 255, 0.9)', backdropFilter: 'blur(10px)', boxShadow: '0px 8px 20px rgba(0, 0, 0, 0.15)' }}>
            <Typography variant="h5" gutterBottom sx={{ fontWeight: 'bold', color: '#333' }}>{section.title}</Typography>
            {section.data.length > 0 ? (
              <Box sx={{ overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                  <thead>
                    <tr style={{ backgroundColor: '#eeeeee' }}>
                      {section.headers.map((head) => (
                        <th key={head} style={{ textAlign: 'left', padding: '10px', fontWeight: 'bold', color: '#555' }}>{head}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {section.data.map((item, i) => (
                      <tr key={item._id} style={{ backgroundColor: i % 2 === 0 ? '#f9f9f9' : 'white', transition: 'background 0.3s' }} 
                        onMouseEnter={(e) => e.currentTarget.style.background = '#d3e3fc'}
                        onMouseLeave={(e) => e.currentTarget.style.background = i % 2 === 0 ? '#f9f9f9' : 'white'}>
                        {index === 0 ? (
                          <>
                            <td style={{ padding: '10px' }}>{item.itemName}</td>
                            <td style={{ padding: '10px' }}>{item.type}</td>
                            <td style={{ padding: '10px', textAlign: 'right' }}>{item.quantity}</td>
                            <td style={{ padding: '10px', textAlign: 'right' }}>${(item.quantity * item.price).toFixed(2)}</td>
                          </>
                        ) : (
                          <>
                            <td style={{ padding: '10px' }}>{item.amount ? 'Income' : 'Expense'}</td>
                            <td style={{ padding: '10px' }}>{item.category?.name || 'N/A'}</td>
                            <td style={{ padding: '10px', textAlign: 'right' }}>${item.amount.toFixed(2)}</td>
                          </>
                        )}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </Box>
            ) : (
              <Typography>No recent transactions</Typography>
            )}
          </Paper>
        </Grid>
      ))}
    </Grid>
  );
};

export default HomePage;
